	start : BOOL;
	stop : BOOL;
	auto : BOOL;
	a : BOOL;
	b : BOOL;
	c : BOOL;
	motor : BOOL;
	lamp : BOOL;
	latch : BOOL;
	x : BOOL;
	y : BOOL;
	speed : INT;
	i : INT;
	j : INT;
	t1 : TON;
	q : BOOL;
END_VAR
%LANGUAGE LD
%NETWORK "Start the motor"
VAR w1 : ANY; w2 : ANY; END_VAR
// runs while auto is on
w1 := INVERT(stop);
w2 := start AND w1;
ASSIGN(w1, Q => ???);
ASSIGN(w2, Q => motor);
ASSIGN(MOVE(EN := w2, 100, OUT => speed), Q => lamp);
%NETWORK "Parallel branch"
ASSIGN(BRANCH(FEED := auto, a, b), Q => x);
%NETWORK "Set and reset"
ASSIGN(a AND b, Q_SET => latch);
ASSIGN(c, Q_RESET => latch);
%NETWORK "Timer"
ASSIGN(t1(IN := a, PT := T#1S), Q => q);
%NETWORK "Edge and compare"
ASSIGN(RISING(a) AND GT(EN := c, i, j, OUT => x), Q => y);
%NETWORK "Two coils"
ASSIGN(a OR INVERT(b), Q => y, Q => x);
%NETWORK "Jump"
ASSIGN(c, Q => JMP.skip);
%NETWORK
skip:
ASSIGN(TRUE, Q => y);
%NETWORK "Return"
%DISABLED
ASSIGN(stop, Q => RETURN);
END_FUNCTION_BLOCK

